unsigned int fn_01(const unsigned char *buf, size_t len)
{
    unsigned int crc = 0xFFFFFFFF;
    size_t i, j;

    for (j = 0; j < len; j++)
    {
        crc ^= buf[j];
        for (i = 0; i < 8; i++)
        {
            crc = (crc >> 1) ^ (0xEDB88320 & -(crc & 1));
        }
    }
    return ~crc;
}
